//! Strongly typed identifiers, versions and sequence numbers.

use serde::{Deserialize, Serialize};
use uuid::Uuid;

macro_rules! define_id {
    ($(#[$meta:meta])* $name:ident) => {
        $(#[$meta])*
        #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
        #[serde(transparent)]
        #[cfg_attr(feature = "specta", derive(specta::Type))]
        pub struct $name(pub Uuid);

        impl $name {
            /// Generates a new time-ordered (UUID v7) identifier.
            ///
            /// Identifiers of new entities are generated by the *client* and carried inside the
            /// intent, so `dnd-game-core` stays deterministic.
            #[must_use]
            pub fn new_v7() -> Self {
                Self(Uuid::now_v7())
            }
        }

        impl std::fmt::Display for $name {
            fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                self.0.fmt(f)
            }
        }
    };
}

define_id!(
    /// A user known to the campaign (GM, players).
    UserId
);
define_id!(
    /// A map inside the campaign.
    MapId
);
define_id!(
    /// A token placed on a map.
    TokenId
);
define_id!(
    /// A character sheet.
    CharacterId
);
define_id!(
    /// An imported asset (image, audio, ...).
    AssetId
);
define_id!(
    /// A journal entry.
    JournalEntryId
);
define_id!(
    /// A chat message (a dice roll is a chat message too).
    ChatMessageId
);
define_id!(
    /// One fog-of-war operation (makes re-applying an event idempotent).
    FogOpId
);
define_id!(
    /// A combat (initiative order) on a map.
    CombatId
);
define_id!(
    /// A folder of the journal (ADR-0021).
    JournalFolderId
);
define_id!(
    /// A participant of a combat.
    CombatantId
);
define_id!(
    /// A board (ADR-0024).
    BoardId
);
define_id!(
    /// An element (card) of a board.
    BoardNodeId
);
define_id!(
    /// A connection between two board nodes.
    BoardEdgeId
);
define_id!(
    /// A named area on a map that triggers watch (ADR-0024).
    ZoneId
);
define_id!(
    /// A trigger: when → if → then, run by the core (ADR-0024).
    TriggerId
);
define_id!(
    /// Client-chosen identifier of an intent, used to correlate `Rejected`/`Events`.
    IntentId
);
define_id!(
    /// A session on the session server.
    SessionId
);
define_id!(
    /// Identifier of a single protocol message (envelope).
    MessageId
);

/// Optimistic-concurrency version of a mutable entity (ADR-0003). Starts at 1.
///
/// Exported to TypeScript as `number`: versions never approach 2^53 (ADR-0007).
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, Default,
)]
#[serde(transparent)]
#[cfg_attr(feature = "specta", derive(specta::Type))]
pub struct Version(
    #[cfg_attr(feature = "specta", specta(type = specta_typescript::Number))] pub i64,
);

impl Version {
    /// Version of a freshly created entity.
    pub const INITIAL: Self = Self(1);

    /// The version after one more change.
    #[must_use]
    pub fn next(self) -> Self {
        Self(self.0.saturating_add(1))
    }
}

/// Position of an event in the campaign/session event log.
///
/// Exported to TypeScript as `number` (ADR-0007).
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, Default,
)]
#[serde(transparent)]
#[cfg_attr(feature = "specta", derive(specta::Type))]
pub struct Seq(#[cfg_attr(feature = "specta", specta(type = specta_typescript::Number))] pub i64);

impl Seq {
    /// The sequence number following this one.
    #[must_use]
    pub fn next(self) -> Self {
        Self(self.0.saturating_add(1))
    }
}

/// Role of a participant (CLAUDE.md §5).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
#[cfg_attr(feature = "specta", derive(specta::Type))]
pub enum Role {
    Gm,
    CoGm,
    Player,
    Spectator,
}

impl Role {
    /// All roles, for exhaustive permission tests.
    pub const ALL: [Self; 4] = [Self::Gm, Self::CoGm, Self::Player, Self::Spectator];

    /// GM or Co-GM.
    #[must_use]
    pub fn is_game_master(self) -> bool {
        matches!(self, Self::Gm | Self::CoGm)
    }
}

impl std::fmt::Display for Version {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.0.fmt(f)
    }
}

impl std::fmt::Display for Seq {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.0.fmt(f)
    }
}

/// A UUIDv7-formatted id from 128 random bits, for ids the core itself creates (system chat
/// messages): deterministic for a seeded RNG, valid for ADR-0015 format checks.
#[must_use]
pub fn uuid_v7_from_random(bits: u128) -> Uuid {
    uuid::Builder::from_u128(bits)
        .with_version(uuid::Version::SortRand)
        .with_variant(uuid::Variant::RFC4122)
        .into_uuid()
}
